mapper.select:
            SELECT
  t.`owner_type` as ownerType,
  t.`owner_id` as ownerId,
  t.remark
FROM
  bi_portal.sys_data_auth t
WHERE t.`module_code` = #{moduleCode}
  AND t.`dim_code` = #{dimCode}
  AND t.`item_code` = #{itemCode}

mapper.delete:
delete from bi_portal.sys_data_auth
where owner_type = 'User'
and (

    (owner_id = #{item.ownerId}
    and module_code = #{item.moduleCode}
    and dim_code = #{item.dimCode}
    and item_code = #{item.itemCode})

)
